     */
    public function __construct(array $data = null)
    {
        parent::__construct($data);

        $this->container['is_residential'] = isset($data['is_residential']) ? $data['is_residential'] : null;
        $this->container['electricity_cap_tar_code'] = isset($data['electricity_cap_tar_code']) ? $data['electricity_cap_tar_code'] : null;
        $this->container['electricity_profile'] = isset($data['electricity_profile']) ? $data['electricity_profile'] : null;
    }

    /**
     * Show all the invalid properties with reasons.
     *
     * @return array invalid properties with reasons
     */
    public function listInvalidProperties()
    {
        $invalidProperties = parent::listInvalidProperties();

        $allowedValues = $this->getElectricityCapTarCodeAllowableValues();
        if (!is_null($this->container['electricity_cap_tar_code']) && !in_array($this->container['electricity_cap_tar_code'], $allowedValues, true)) {
            $invalidProperties[] = sprintf(
                "invalid value for 'electricity_cap_tar_code', must be one of '%s'",
                implode("', '", $allowedValues)
            );
        }

        $allowedValues = $this->getElectricityProfileAllowableValues();
        if (!is_null($this->container['electricity_profile']) && !in_array($this->container['electricity_profile'], $allowedValues, true)) {
            $invalidProperties[] = sprintf(
                "invalid value for 'electricity_profile', must be one of '%s'",
                implode("', '", $allowedValues)
            );
        }

        return $invalidProperties;
    }

    /**
     * Validate all the properties in the model
     * return true if all passed
     *
     * @return bool True if all properties are valid
     */
